syntax:
class Base {
    public:
        virtual void foo();  // Declares a virtual function; compiler adds vptr to class layout and synthesizes a vtable.
};

class Derived : public Base {
    public:
        void foo() override;  // Overrides the virtual function; compiler updates the vtable for Derived to point to this implementation.
};

// Implementation note: The compiler generates assembly like:
// mov rax, [obj]    ; Load object address
// mov rax, [rax]    ; Load vptr from object
// call [rax + offset] ; Index into vtable and call the function

code_example:
#include <iostream>

class Base {
public:
    virtual void foo() { std::cout << "Base::foo" << std::endl; }  // Virtual function
};

class Derived : public Base {
public:
    void foo() override { std::cout << "Derived::foo" << std::endl; }  // Overrides virtual function
};

int main() {
    Base* ptr = new Derived();  // Pointer to Base, but points to Derived object
    ptr->foo();  // Virtual dispatch: Calls Derived::foo() at runtime
    delete ptr;
    return 0;
}
